import sys


def make_greeting(name, hour):
    if 5 <= hour <= 11:
        return "Good morning, " + name + "!"
    if 12 <= hour <= 16:
        return "Good afternoon, " + name + "!"
    if 17 <= hour <= 21:
        return "Good evening, " + name + "!"
    return "Good night, " + name + "!"


data = sys.stdin.read().split()
name = data[0]
hour = int(data[1])
sys.stdout.write(make_greeting(name, hour) + "\n")

import sys


def bmi_report(weight_kg, height_m):
    bmi = weight_kg / (height_m * height_m)
    if bmi < 18.5:
        return (bmi, "UNDERWEIGHT")
    if bmi < 25:
        return (bmi, "NORMAL")
    if bmi < 30:
        return (bmi, "OVERWEIGHT")
    return (bmi, "OBESE")


data = sys.stdin.read().split()
bmi, category = bmi_report(float(data[0]), float(data[1]))
sys.stdout.write("{:.1f} {}\n".format(bmi, category))

import sys


def parking_fee(hours):
    if hours <= 0:
        return 0
    extra = int(hours - 1)
    if extra < 0:
        extra = 0
    fee = 20 + 15 * extra
    if fee > 100:
        fee = 100
    return fee


hours = float(sys.stdin.read().strip())
sys.stdout.write(str(parking_fee(hours)) + "\n")

