import sys


def taxi_fare(km, night):
    if km <= 0:
        return 0.0
    fare = 50.0
    if km > 2:
        fare += int(km - 2) * 18.0
    if night:
        fare *= 1.2
    return fare


data = sys.stdin.read().split()
sys.stdout.write("{:.2f}\n".format(taxi_fare(float(data[0]), int(data[1]))))

import sys


def electricity_bill(units):
    if units <= 100:
        bill = units * 3.5
    elif units <= 200:
        bill = 100 * 3.5 + (units - 100) * 5.0
    else:
        bill = 100 * 3.5 + 100 * 5.0 + (units - 200) * 8.0
    return bill + 90


units = int(sys.stdin.read().strip())
sys.stdout.write("{:.2f}\n".format(electricity_bill(units)))
